import { appendFileSync } from 'node:fs';

let launches = 0;

function record(event) {
  appendFileSync(process.env.FAKE_PLAYWRIGHT_LOG, `${event}\n`);
}

function cdpSession(browserNumber) {
  return {
    on: () => {},
    send: async method => {
      if (method === 'Page.getFrameTree') {
        return { frameTree: { frame: { id: 'main-frame' } } };
      }
      if (method === 'Fetch.enable' && browserNumber === 1) {
        record(`browser ${browserNumber}: Fetch.enable rejected`);
        throw new Error('Fetch.enable rejected');
      }
      record(`browser ${browserNumber}: ${method}`);
      return {};
    },
  };
}

export const chromium = {
  launch: async () => {
    launches += 1;
    const browserNumber = launches;
    let currentUrl = 'about:blank';
    const page = {
      goto: async url => {
        record(`browser ${browserNumber}: goto ${url}`);
        currentUrl = url;
      },
      url: () => currentUrl,
    };
    const context = {
      newPage: async () => page,
      newCDPSession: async () => cdpSession(browserNumber),
    };
    page.context = () => context;
    return {
      newContext: async () => context,
      close: async () => record(`browser ${browserNumber}: closed`),
    };
  },
};
